// ========== SEGURANÇA & PROTEÇÃO ANTI-DEVTOOLS ==========
(function initSecurity() {
  // Bloqueia clique direito (context menu)
  document.addEventListener('contextmenu', function(e) {
    e.preventDefault();
    if (typeof showToast === 'function') showToast('🔒 Menu de contexto desativado por segurança');
    return false;
  });

  // Bloqueia atalhos de DevTools (F12, Ctrl+Shift+I/J/C, Ctrl+U, Ctrl+S)
  document.addEventListener('keydown', function(e) {
    if (
      e.key === 'F12' ||
      e.keyCode === 123 ||
      (e.ctrlKey && e.shiftKey && ['I', 'i', 'J', 'j', 'C', 'c'].includes(e.key)) ||
      (e.ctrlKey && ['u', 'U', 's', 'S'].includes(e.key))
    ) {
      e.preventDefault();
      e.stopPropagation();
      if (typeof showToast === 'function') showToast('🔒 Atalho bloqueado por motivos de segurança');
      return false;
    }
  });

  // Marca d'água na consola
  try {
    console.clear();
    console.log(
      '%c🐍 BLACK MAMBA — SISTEMA PRIVADO\n%cTodos os dados deste site são encriptados com AES-256-GCM.\nTentativas de engenharia reversa ou cópia não autorizada são registadas.',
      'color: #a78bfa; font-size: 16px; font-weight: bold;',
      'color: #ef4444; font-size: 12px;'
    );
  } catch(e) {}
})();

